while True:
    res=apis.amazon.search_product_types(query='game', page_index=page_index, page_limit=50)
    if not res:
        break
    for t in res:
        if t not in seen:
            seen.add(t)
            types.append(t)
    page_index+=1
    if page_index>10:
        break

# filter types to likely board/card/puzzle games
keywords_type=['board','card','dice','monopoly','catan','chess','scrabble','risk','dungeon','table','tabletop','puzzle','game']
# create a set of types containing any of these substrings
likely_types=[]
for t in types:
    lt=t.lower()
    if any(k in lt for k in ['board','card game','dice','monopoly','catan','chess','scrabble','risk','dungeon','tabletop','table','puzzle','card','game']):
        likely_types.append(t)

print('Total game types:', len(types))
print('Likely types count:', len(likely_types))
print('Likely types sample:', likely_types[:40])

name_keywords=['board','game','codenames','monopoly','dungeon','catan','chess','scrabble','risk','pandemic','dominion','cards','deck','dice','tabletop','cards']

def name_match(name):
    nm=(name or '').lower()
    return any(k in nm for k in name_keywords)

qual=[]
for pt in likely_types:
    page_index=0
    page_limit=20
    fetched=0
    while True:
        page=apis.amazon.search_products(query='', product_type=pt, min_product_rating=min_rating, max_price=max_price, page_index=page_index, page_limit=page_limit, sort_by='-rating')
        if not page:
            break
        fetched+=len(page)
        for p in page:
            if p.get('price',0) < strict_price_lt and p.get('rating',0) > min_rating and p.get('num_product_reviews',0) > min_reviews and name_match(p.get('name','')):
                qual.append(p)
        page_index+=1
        if page_index>20:
            break
    if fetched:
        print('pt', pt, 'fetched', fetched, 'qual_so_far', len(qual))

